import {cf} from './chinese-first.js';
import {gameId,config,clone,isDone,count,edit,undoEdit,envelope,importData,differences,applyDifferences} from './model.js';
import {renderLayout,renderImage} from './layouts.js';
const {createStore}=await import(new URL(location.pathname.includes('/dist/')?'../../../shared/roadmap-store.js':'../../shared/roadmap-store.js',import.meta.url));
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,progress,ready=false,busy=false,queued=false,search='',status='pending',category='',target='',lastUndo,retry,review,dailyMode='natural';
const peeks=new Set(),params=()=>new URLSearchParams(location.search),view=()=>params().get('view')||'home',chapter=()=>params().get('chapter')||'c01';
const layoutModes=new Map(),playingFigures=new Set();let figureTrigger=null;
const store=createStore(config,{clone},()=>{if(busy){queued=true;return;}refresh();});
async function refresh(){if(!ready)return;try{progress=await store.get();if(review)review.expired=true;gate();render(true);}catch(e){message('讀取失敗：'+e.message);ready=false;}}
function drainUpdates(){if(queued){queued=false;refresh();}}
const message=text=>$('feedback').textContent=text;
const href=(v,extra={})=>'?'+new URLSearchParams({view:v,...extra});
const link=(v,label,extra={})=>`<a data-route href="${esc(href(v,extra))}">${esc(label)}</a>`;
const done=(g,id)=>isDone(progress,g,id),puzzleDone=p=>p.solutionIds.every(id=>done('solutions',id));
const nextPuzzle=()=>data.puzzles.find(p=>!puzzleDone(p));
const searchText=v=>cf.search(JSON.stringify(v)).toLocaleLowerCase();
function check(group,id,label){return `<label class="check"><input id="check-${esc(id)}" type="checkbox" data-group="${group}" data-id="${esc(id)}" ${done(group,id)?'checked':''}><span>${esc(label)}</span></label>`;}
function inline(text){return esc(text).replace(/`([^`]+)`/g,'<strong>$1</strong>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[(S\d+(?:、S\d+)*)\]/g,'<span class="source-tag">[$1]</span>');}
function markdown(text){let list=false,table=false;let out='';for(const line of text.split('\n')){
 if(line.startsWith('|')){if(!table){out+='<div class="table-scroll"><table><thead><tr>'+line.split('|').slice(1,-1).map(c=>'<th scope="col">'+inline(c.trim())+'</th>').join('')+'</tr></thead><tbody>';table=true;continue;}if(/^\|[- :|]+\|$/.test(line))continue;out+='<tr>'+line.split('|').slice(1,-1).map(c=>'<td>'+inline(c.trim())+'</td>').join('')+'</tr>';continue;}
 if(table){out+='</tbody></table></div>';table=false;}
 const m=line.match(/^\d+\. (.*)/);if(m){if(!list){out+='<ol>';list=true;}out+='<li>'+inline(m[1])+'</li>';continue;}
 if(list){out+='</ol>';list=false;}if(line.trim())out+='<p>'+inline(line.replace(/^- /,''))+'</p>';
 }return '<div class="prose">'+out+(list?'</ol>':'')+(table?'</tbody></table></div>':'')+'</div>';}
function stats(){return `<div class="stats">${[['solutions','已記錄解法',data.solutions,'missing'],['trophies','實際跳盃',data.trophies,'trophies'],['steps','已核對操作',data.steps,'roadmap']].map(([g,label,rows,v])=>{const n=count(progress,g,rows),pct=Math.floor(n/rows.length*100);return `<a class="stat" data-route href="${href(v)}"><span>${label}</span><strong>${n} / ${rows.length}</strong><progress value="${n}" max="${rows.length}" aria-label="${label}"></progress><span>${pct}% · ${g==='solutions'?'本站解法紀錄，非官方總星數':g==='steps'?'操作與解法分別確認':'PS5 本體'}</span></a>`;}).join('')}</div>`;}
function cleanWarning(){return `<div class="warning"><strong>首輪不開 Hint，不用 Let It Be。</strong><br>先取得 No Squint Hint 與 No Mess Left Behind，再做提示／跳關收尾。正常重試與選關可以使用；已用過時保留存檔，先核對補救方式。</div>`;}
function toolbar(extra=''){return `<div class="toolbar"><label>搜尋題名、原文或編號<input type="search" id="search" value="${esc(search)}"></label><label>顯示<select id="status">${[['pending','未完成'],['all','全部'],['done','已完成']].map(([v,t])=>`<option value="${v}" ${status===v?'selected':''}>${t}</option>`).join('')}</select></label>${extra}<button data-reset>清除條件</button></div>`;}
const empty=()=>'<div class="empty">目前條件沒有結果。<button data-reset>清除條件</button></div>';
function match(row,completed){return searchText(row).includes(search.toLocaleLowerCase())&&(status==='all'||(status==='done'?completed:!completed));}
function sourceLinks(ids){return ids.flatMap(id=>data.sources.find(s=>s.id===id)?.links||[]).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a>`).join(' · ');}
function findFigure(id){for(const p of data.puzzles){const figure=p.layout?.figures.find(f=>f.figureId===id);if(figure)return {...figure,markers:figure.number===1?p.layout.markers:[]};}throw Error('找不到這張配置圖');}
function restoreAnimationState(){for(const id of playingFigures){const f=findFigure(id);document.querySelectorAll(`[data-image-figure="${id}"]`).forEach(el=>{el.querySelector('img').src='./'+f.animationFile;el.classList.add('playing');});document.querySelectorAll(`[data-play="${id}"]`).forEach(button=>{button.textContent='停止步驟示範';button.setAttribute('aria-pressed','true');});}}
function openFigure(id,trigger){const f=findFigure(id);figureTrigger=trigger;$('layout-dialog-title').textContent='圖 '+f.number+' · '+f.caption;$('layout-dialog-content').innerHTML=renderImage(f,{large:true});$('layout-dialog-content').classList.remove('actual-size');$('layout-original-size').setAttribute('aria-pressed','false');$('layout-original-size').textContent='原始尺寸';$('layout-dialog-source').href=f.sourceUrl;$('layout-dialog-credit').textContent='遊戲畫面／來源：'+f.author+(f.captureSeconds!==undefined?' · 影片 '+f.captureSeconds+' 秒':'');$('layout-dialog-play').hidden=!f.animationFile;$('layout-dialog-play').dataset.play=id;$('layout-dialog-play').textContent='播放步驟示範';$('layout-dialog-play').setAttribute('aria-pressed','false');$('layout-dialog').showModal();restoreAnimationState();}
function guide(p){const rows=data.steps.filter(s=>s.puzzleId===p.id);return markdown(p.body.split('\n').filter(line=>!/^\d+\. /.test(line)).join('\n'))+rows.map((s,i)=>`<div class="step-row">${check('steps',s.id,(i+1)+'. '+s.titleZh)}</div>`).join('');}
function trophyRow(t,embedded=false){return `<div class="row" id="entry-${esc(t.id)}">${check('trophies',t.id,t.name)}${!embedded||!done('trophies',t.id)?`<p class="muted">${esc(t.guide)} · ${esc(t.category)}</p>${t.puzzleId?link('roadmap','前往操作與條件',{chapter:t.puzzleId.slice(11,14),target:t.puzzleId}):''}`:''}</div>`;}
function conditions(p){return data.trophies.filter(t=>t.slug!=='be-chaos'&&(t.puzzleId===p.id||(t.slug==='sweep-floor'&&p.key==='c02-p07')));}
function puzzleRow(p,compact=false){const complete=puzzleDone(p),open=!complete||peeks.has(p.id)||target===p.id;
 const events=conditions(p),important=events.filter(t=>!done('trophies',t.id));
 return `<article class="puzzle ${target===p.id?'target':''}" id="entry-${p.id}"><header><div><small>${esc(p.key)} · ${p.solutionIds.filter(id=>done('solutions',id)).length} / ${p.solutionIds.length} 個解法</small><h2>${esc(p.titleZh)}</h2></div>${complete?`<button data-peek="${p.id}" aria-expanded="${open}">${open?'收合':'回看攻略'}</button>`:''}</header>${important.length?`<div class="warning"><strong>操作前先看</strong>${important.map(t=>`<p>${esc(t.name)}：${esc(t.guide)}</p>`).join('')}${p.key==='c02-p06'?'<p>從原始布局只移兩次，試移過請先正常重試。</p>':''}${p.key==='c02-p11'?'<p>固定搗亂後，擋爪與搶先完成分兩次挑戰。</p>':''}${p.key==='c03-p06'?'<p>先排右下蠟筆：紅、橙、黃、綠、藍，再收納其他文具。</p>':''}</div>`:''}
 ${open?`<div class="body">${p.key==='c05-p12'?'<div class="warning">名單出現前：不要跳過，拍到每個職稱與每位工作人員的名字或姓氏，爭取 Be The Chaos。</div>':''}${p.preciseLayoutStatus==='needed'?'<p class="layout-gap"><strong>配置內容待補：</strong>本題尚缺核實的完整配置圖／逐件表。下方文字與來源可參照，尚未達自足圖解驗收。</p>':''}${guide(p)}${renderLayout(p,layoutModes.get(p.key)||'normal')}${p.supplement?`<section class="notice"><h3>${esc(p.supplement.title)}</h3><ol>${p.supplement.steps.map(s=>`<li>${esc(s)}</li>`).join('' )}</ol><p>${esc(p.supplement.note)}</p></section>`:''}${p.key==='c02-p06'?eggDiagram():''}<div class="actions">${sourceLinks(p.sourceIds)}</div></div>`:''}
 ${p.solutionIds.map(id=>{const s=data.solutions.find(s=>s.id===id),isComplete=done('solutions',id);return `<div class="solution ${isComplete?'done':''}">${check('solutions',id,s.titleZh+'｜已在遊戲完成')}${!isComplete&&open?`<small>${esc(s.completionCheck)}</small>`:''}</div>`;}).join('')}
 ${events.length?`<details ${important.length&&open?'open':''}><summary>實際跳盃核對（獨立紀錄）</summary>${events.map(t=>trophyRow(t,true)).join('')}</details>`:''}
 </article>`;}
function eggDiagram(){return '<figure><figcaption>兩次移動表（從原始局面，左起計數）</figcaption><div class="egg-grid">'+['上 1','上 2','上 3','上 4','上 5','上 6','下 1','下 2','下 3','下 4','下 5','下 6'].map((s,i)=>`<span class="${[0,1,2,10].includes(i)?'move':''}">${s}${i===0?'：移出①':i===1?'：放入①':i===2?'：移出②':i===10?'：放入②':''}</span>`).join('')+'</div><small>依規格文字製作；未於 PS5 實機驗證。</small></figure>';}
function home(){const n=nextPuzzle(),start=progress.settings.start?.value;return `<h1>繼續整理</h1><p class="muted">五章主線與每日整理並行，特殊獎盃放在操作之前。</p>${cleanWarning()}<div class="home-grid"><section class="panel"><h2>${n?'下一個未完成題':'主線解法已記錄'}</h2>${n?`<small>${esc(data.chapters.find(c=>c.id===n.chapterId).title)} · ${esc(n.key)}</small><h3>${esc(n.titleZh)}</h3><p>仍缺 ${n.solutionIds.filter(id=>!done('solutions',id)).map(id=>esc(data.solutions.find(s=>s.id===id).titleZh)).join('、')}</p><button class="primary" id="continue">返回遊玩進度</button>`:link('trophies','核對未取得獎盃')}<p>${link('roadmap','自由閱讀任一章')}</p></section><section class="panel"><h2>每日整理</h2><p>可從首日開始。先守住連續 30 日；累積星、連續數、徽章分開核對。</p><p>遊戲顯示星數：${progress.counters.stars?.value??'尚未確認'}<br>遊戲顯示連續數：${progress.counters.streak?.value??'尚未確認'}</p>${link('daily','自然日期／選用調日期指引')}</section></div>${stats()}<section class="panel"><h2>目前存檔狀況</h2><p>只記錄你確認的狀況，不會修改 PS5 存檔。</p><div class="actions">${[['new','尚未開始'],['clean','已開始，未用提示／跳關'],['used','已用過／不確定']].map(([v,t])=>`<button data-start="${v}" aria-pressed="${start===v}">${t}</button>`).join('')}</div>${start==='used'?'<p class="warning">保留現有存檔，先完成剩餘內容；PS5 重設範圍與補救方式尚待核對。</p>':''}</section><p class="muted">79 個編輯導航單元／108 個本站解法紀錄；非官方關卡數或已核實總星數。原列 ${data.layoutCoverage.required} 題配置已收錄 ${data.layoutCoverage.complete} 題，含 ${data.layoutCoverage.figures} 張本機圖解與 ${data.layoutCoverage.animations} 組可播放步驟。詳見${link('sources','來源與缺口')}。</p>`;}
function road(){const c=data.chapters.find(c=>c.id===chapter())||data.chapters[0],rows=data.puzzles.filter(p=>p.chapterId===c.id&&match(p,puzzleDone(p)));return `<h1>第 ${c.order} 章 · ${esc(c.title)}</h1><p class="muted">目前閱讀單元內未完成內容全展開。提前看後章不會完成前章。</p><div class="actions"><button id="continue">返回遊玩進度</button>${link('missing','查漏所有章節')}</div>${cleanWarning()}${toolbar()}<nav class="read-index" aria-label="本章題目">${rows.map(p=>`<a href="#entry-${p.id}">${esc(p.order+' '+p.titleZh.split('，')[0])}</a>`).join('')}</nav>${rows.map(p=>puzzleRow(p)).join('')||empty()}${c.id==='c05'?`<section class="panel"><h2>製作人員名單</h2><div class="warning">名單出現前先讀：不要跳過。</div>${markdown(data.credits)}${trophyRow(data.trophies.find(t=>t.slug==='be-chaos'),true)}</section>`:''}`;}
function missing(){const rows=data.solutions.filter(s=>match({...s,puzzle:data.puzzles.find(p=>p.id===s.puzzleId)},done('solutions',s.id))&&(!category||s.puzzleId.includes(':'+category+'-')));return `<h1>解法查漏</h1><p class="muted">本站已列 108 個解法紀錄，非官方星數。尚缺 ${data.solutions.filter(s=>!done('solutions',s.id)).length} 個；解法與 PSN 獎盃各自確認。</p>${toolbar(chapterFilter())}${rows.map(s=>{const p=data.puzzles.find(p=>p.id===s.puzzleId);return `<article class="row" id="entry-${s.id}">${check('solutions',s.id,p.titleZh+' · '+s.titleZh)}${link('roadmap','返回此題完整步驟',{chapter:p.chapterId,target:p.id})}</article>`;}).join('')||empty()}`;}
function chapterFilter(){return `<label>章節<select id="category"><option value="">全部章節</option>${data.chapters.map(c=>`<option value="${c.id}" ${category===c.id?'selected':''}>${c.order} ${esc(c.title)}</option>`).join('')}</select></label>`;}
function trophies(){return `<h1>獎盃與收尾</h1><p>${count(progress,'trophies',data.trophies)} / 48 座本體獎盃已確認；付費 DLC 排除。新增中文名稱為本站參考譯名，英文保留作對照。</p>${toolbar(`<label>分組<select id="category"><option value="">全部分組</option>${[...new Set(data.trophies.map(t=>t.category))].map(c=>`<option ${category===c?'selected':''}>${c}</option>`).join('')}</select></label>`)}${data.trophies.filter(t=>match(t,done('trophies',t.id))&&(!category||category===t.category)).map(t=>trophyRow(t)).join('')||empty()}<h2>通關後收尾</h2>${data.cleanup.map(c=>{const gateId=c.id==='cleanup-hints'?'no-squint-hint':c.id==='cleanup-skips'?'no-mess-left-behind':null,allowed=!gateId||done('trophies','alttl:t:'+gateId);return `<section class="panel"><h3>${esc(c.title)}</h3>${allowed?markdown(c.body):`<p class="warning">先在 PS5 確認 ${gateId==='no-squint-hint'?'No Squint Hint':'No Mess Left Behind'}，並在上方獎盃清單勾選，才提供此收尾的操作指引。尚未確認，避免污染乾淨首輪。</p>`}${c.id==='cleanup-items'?counter('items','遊戲顯示整理次數（不知道時留空）'):''}</section>`;}).join('')}`;}
function counter(id,label){return `<label>${label}<input type="number" min="0" step="1" data-counter="${id}" id="counter-${id}" value="${progress.counters[id]?.value??''}"></label>`;}
function daily(){return `<h1>每日整理</h1><p>自然日期或選用調日期皆可；網站不產生「今天固定答案」，也不從日期推定遊戲已完成。</p><div class="tabs">${[['natural','自然日期'],['accelerated','調日期加速']].map(([v,t])=>`<button data-daily-mode="${v}" aria-pressed="${dailyMode===v}">${t}</button>`).join('')}</div><section class="panel">${markdown(dailyMode==='natural'?data.dailyNatural:data.dailyAccelerated)}</section><section class="panel"><h2>手動核對遊戲顯示值</h2><p>值只由你更新。網站不把連續獎勵加進星數，也不自動勾獎盃；留空表示未確認。</p><div class="daily-fields">${counter('stars','累積星數')}${counter('streak','連續完成數')}<label>主機遊戲日期<input type="date" id="console-date" value="${esc(progress.settings.consoleDate?.value||'')}"></label><div><span>玩家記錄時間</span><p id="recorded-at">${progress.settings.consoleDate?.updatedAt?esc(new Date(progress.settings.consoleDate.updatedAt).toLocaleString('zh-TW')):'尚未記錄'}</p></div></div><h3>遊戲徽章階級（依實際畫面勾選）</h3><p class="muted">逐階徽章名稱與門檻尚待 PS5 核對；目前僅記錄玩家確認的全部徽章狀態。</p><div class="actions">${check('badges','alttl:daily:all-badges','已在遊戲徽章頁確認全部徽章')}</div><details><summary>每日整理獎盃</summary>${data.trophies.filter(t=>t.category==='每日整理').map(t=>trophyRow(t,true)).join('')}</details></section><h2>依題型找規則</h2><label>搜尋題型<input type="search" id="search" value="${esc(search)}"></label>${data.dailyTypes.filter(t=>searchText(t).includes(search.toLocaleLowerCase())).map(t=>`<section class="row"><h3>${esc(t.title)}</h3><p>${esc(t.rule)}</p><div class="inline-links">${[...t.references.matchAll(/c\d{2}-p\d{2}/g)].map(m=>link('roadmap',m[0],{chapter:m[0].slice(0,3),target:'alttl:base:'+m[0]})).join('')}</div><small>${esc(t.references)}</small></section>`).join('')||empty()}`;}
function sources(){const c=data.layoutCoverage,covered=data.puzzles.filter(p=>p.layout);return `<h1>資料與來源</h1><p>資料版本 ${esc(data.datasetVersion)} · 本體 48 盃／79 個編輯導航單元／108 解法／200 操作核對。</p><div class="notice"><strong>原列配置題 ${c.complete} / ${c.required} 已收錄圖文</strong><p>${c.figures} 張本機圖解、${c.animations} 組可播放操作示範，另有月曆貼紙圖案。所有圖都隨網站提供，不需要開外站才能看答案。</p></div><p>2026-11-27 逐題核對 Abbilieve 五章完成圖與動態圖，整理繁中格位、方向、配方及步驟。原始完成圖／標註由 Abbilieve 擷取，花瓶旋轉圖另取自 GameStockFootage 公開實玩影片；本站新增物件對照表與數字圓標；圖片保留來源段落與 SHA256 紀錄。</p><h2>本機配置索引</h2><div class="layout-index">${covered.map(p=>`<div class="row">${link('roadmap',p.key+' '+p.titleZh,{chapter:p.chapterId,target:p.id})}<small>${p.layout.figures.length} 張圖 · ${p.layout.tables.reduce((n,t)=>n+t.rows.length,0)} 列操作／位置說明</small></div>`).join('')}</div><h2>查證範圍與版本差異</h2><ul><li>來源畫面核對完成，不等於 PS5 實機驗收。安裝版、手把按鍵、官方總星數與每日刷新仍需遊戲端核對。</li><li>普通／色彩輔助外觀分開顯示，共用解法紀錄，不增加星星分母。</li><li>畫框轉向以六段動態圖的實際滾動結果為準；橙色火柴保留來源配方差異，依成色判斷。</li><li>燈光題是七個框區，第五區包含上下兩個開關；表格已明列。</li><li>花瓶附完整正面及八張旋轉過程畫面，影片時間點與各面缺口列入操作表。自由對稱題提供一組有效完整配置，不枚舉所有自由擺法。</li></ul><h2>額外交叉核對</h2>${covered.flatMap(p=>(p.layout.crossChecks||[]).map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a></p>`)).join('')}<h2>原規格來源清單</h2>${data.sources.map(s=>`<section class="source-row"><h3>${s.id}</h3>${sourceLinks([s.id])}<p>${esc(s.note)}</p><small>規格查閱日 ${s.checkedAt} · 社群資料不代表 PS5 實測</small></section>`).join('')}<h2>本機紀錄</h2><p>獨立 IndexedDB：game-companion.alttl.progress.v1。資料更新保留原 200 個操作與 108 個解法的 ID／勾選；圖片閱讀、放大、播放與切外觀不修改進度。</p><button data-open-backup>備份與還原</button>`;}
function render(preserve=false){if(!ready)return;const y=scrollY,active=document.activeElement,focusId=active?.id,controls=[...$('main').querySelectorAll('input,button,a,select')],index=controls.indexOf(active),selection=active?.type==='search'?[active.selectionStart,active.selectionEnd]:null;
 const anchor=[...$('main').querySelectorAll('.puzzle,.row')].find(el=>el.getBoundingClientRect().top>=0),anchorId=anchor?.id,anchorY=anchor?.getBoundingClientRect().top;
 const openDetails=new Set([...$('main').querySelectorAll('details[open]')].map(el=>el.closest('[id]')?.id+'|'+el.querySelector('summary')?.textContent));
 $('main').innerHTML=({home,roadmap:road,missing,trophies,daily,sources}[view()]||home)();
 cf.decorate($('main'));cf.notice($('main'));restoreAnimationState();
 document.querySelectorAll('[data-view]').forEach(a=>a.setAttribute('aria-current',a.dataset.view===view()?'page':'false'));
 $('chapter-nav').innerHTML=data.chapters.map(c=>`<a data-route href="${href('roadmap',{chapter:c.id})}" ${view()==='roadmap'&&chapter()===c.id?'aria-current="page"':''}>${c.order}. ${esc(c.title)}<small>${data.puzzles.filter(p=>p.chapterId===c.id&&puzzleDone(p)).length} / ${data.puzzles.filter(p=>p.chapterId===c.id).length} 題</small></a>`).join('');
 cf.decorate($('chapter-nav'));if(preserve){$('main').querySelectorAll('details').forEach(el=>{if(openDetails.has(el.closest('[id]')?.id+'|'+el.querySelector('summary')?.textContent))el.open=true;});let el=focusId?$(focusId):null;if(!el&&index>=0)el=[...$('main').querySelectorAll('input,button,a,select')][Math.min(index,$('main').querySelectorAll('input,button,a,select').length-1)]||$('main');el?.focus({preventScroll:true});if(selection&&el?.type==='search')el.setSelectionRange(...selection);const same=anchorId&&$(anchorId);scrollTo(0,same?y+same.getBoundingClientRect().top-anchorY:y);}}
function reset(){search='';status=view()==='roadmap'?'all':'pending';category='';target='';}
function navigate(v,extra={}){history.pushState({},'',href(v,extra));reset();target=extra.target||'';if(target)status='all';render();if(matchMedia('(max-width:720px)').matches)$('menu').open=false;requestAnimationFrame(()=>{const el=target&&$('entry-'+target);if(el){el.scrollIntoView({block:'start'});(el.querySelector('input,button')||el).focus({preventScroll:true});}else{scrollTo(0,0);$('main').focus({preventScroll:true});}});}
async function save(g,id,value){if(busy)return;busy=true;retry=()=>save(g,id,value);try{const result=await edit(store,g,id,value);progress=result.progress;lastUndo=result.undo;$('undo').hidden=false;$('retry').hidden=true;retry=null;message('已保存，可撤銷這一筆。');if(review)review.expired=true;render(true);}catch(e){message('保存失敗：'+e.message+'；尚未保存，原資料保留。');$('retry').hidden=false;render(true);}finally{busy=false;drainUpdates();}}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');try{a.href=url;a.download=name;a.click();}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}}
function openBackup(){if(!ready)return;$('backup-save-state').textContent='此瀏覽器已保存修訂 '+progress.revision;$('backup-dialog').showModal();}
const safely=fn=>async e=>{try{await fn(e);}catch(error){message(error.message);}};
document.addEventListener('click',safely(async e=>{const route=e.target.closest('[data-view],[data-route]');if(route){e.preventDefault();const u=new URL(route.href);navigate(u.searchParams.get('view')||'home',Object.fromEntries([...u.searchParams].filter(([k])=>k!=='view')));return;}const el=e.target.closest('button');if(!el)return;
 if(el.id==='open-backup'||el.hasAttribute('data-open-backup'))openBackup();
 if(el.id==='backup-close')$('backup-dialog').close();
 if(el.id==='import-open')$('import-file').click();
 if(el.hasAttribute('data-reset')){reset();render();}
 if(el.dataset.peek){peeks.has(el.dataset.peek)?peeks.delete(el.dataset.peek):peeks.add(el.dataset.peek);render(true);}
 if(el.dataset.layoutMode){layoutModes.set(el.dataset.puzzleKey,el.dataset.layoutMode);render(true);}
 if(el.dataset.enlarge)openFigure(el.dataset.enlarge,el);
 if(el.dataset.play){const id=el.dataset.play,f=findFigure(id);if(!f.animationFile)return;if(playingFigures.has(id)){playingFigures.delete(id);document.querySelectorAll(`[data-image-figure="${id}"]`).forEach(box=>{box.querySelector('img').src='./'+f.file;box.classList.remove('playing');});document.querySelectorAll(`[data-play="${id}"]`).forEach(button=>{button.textContent='播放步驟示範';button.setAttribute('aria-pressed','false');});}else{playingFigures.add(id);restoreAnimationState();}}
 if(el.id==='layout-close')$('layout-dialog').close();
 if(el.id==='layout-original-size'){const actual=$('layout-dialog-content').classList.toggle('actual-size');el.setAttribute('aria-pressed',String(actual));el.textContent=actual?'適合視窗':'原始尺寸';}
 if(el.dataset.start)await save('settings','start',{value:el.dataset.start});
 if(el.dataset.dailyMode){dailyMode=el.dataset.dailyMode;render(true);}
 if(el.id==='continue'){const p=nextPuzzle();navigate(p?'roadmap':'trophies',p?{chapter:p.chapterId,target:p.id}:{});}
 if(el.id==='export-progress')download(envelope(await store.get()),'alttl-progress.json');
 if(el.id==='export-all')download(await store.exportAll(),'alttl-recovery.json');
 if(el.id==='undo'&&lastUndo){busy=true;try{progress=await undoEdit(store,lastUndo);lastUndo=null;el.hidden=true;message('已撤銷該筆，其他紀錄保留。');render(true);}finally{busy=false;drainUpdates();}}
 if(el.id==='retry'&&retry)await retry();
}));
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;render(true);}});
document.addEventListener('change',safely(async e=>{const el=e.target;if(el.dataset.group){await save(el.dataset.group,el.dataset.id,{done:el.checked});return;}
 if(el.id==='status'){status=el.value;render(true);}if(el.id==='category'){category=el.value;render(true);}
 if(el.dataset.counter){if(el.value===''){await save('counters',el.dataset.counter,{value:null});return;}const value=Number(el.value);if(!Number.isSafeInteger(value)||value<0)throw Error('請輸入非負整數');await save('counters',el.dataset.counter,{value});}
 if(el.id==='console-date')await save('settings','consoleDate',{value:el.value});
 if(el.id==='import-file'&&el.files[0]){const file=el.files[0];$('backup-dialog').close();try{await preview(file);}finally{el.value='';}}
}));
window.addEventListener('popstate',()=>{reset();target=params().get('target')||'';if(target)status='all';render();});
// 匯入的兩端原文、差異與過期條件沿用現有本機模組的保護流程。
async function preview(file){
 if(file.size>10*1024*1024)throw Error('檔案超過 10 MB，停止匯入。');const sourceRaw=await file.text(),local=await store.raw(),localRaw=JSON.stringify(local);
 await store.archive({sourceRaw,localRaw,at:new Date().toISOString(),name:file.name});
 const incoming=importData(JSON.parse(sourceRaw));review={sourceRaw,localRaw,stamp:localRaw,rows:differences(local,incoming),downloaded:false,expired:false};
 $('diff-rows').innerHTML=review.rows.map((r,i)=>`<div class="diff-row"><label class="check"><input type="checkbox" data-diff="${i}" ${r.missing?'disabled':''}><span>${esc(r.group+' / '+r.id)}${r.missing?' · 來源缺少，保留本機':r.older?' · 來源較舊，需額外核對':''}</span></label><pre>本機：${esc(JSON.stringify(r.local)??'無紀錄')}\n來源：${esc(JSON.stringify(r.incoming)??'無紀錄')}</pre></div>`).join('')||'<p>兩端紀錄相同。</p>';
 $('import-status').textContent=review.rows.length+' 筆差異，未勾選項目保留本機。';$('import-ack').checked=false;$('import-ack').disabled=true;$('older-ack').checked=false;gate();$('import-dialog').showModal();
}
function gate(){$('import-apply').disabled=!review||review.expired||!review.downloaded||!$('import-ack').checked;}
 $('choose-source').onclick=()=>document.querySelectorAll('[data-diff]:not(:disabled)').forEach(x=>x.checked=true);
 $('choose-local').onclick=()=>document.querySelectorAll('[data-diff]').forEach(x=>x.checked=false);
 $('download-recovery').onclick=()=>{try{if(review.expired)throw Error('預覽已過期');download({gameId,recoveryBundle:{localRaw:review.localRaw,sourceRaw:review.sourceRaw},progress:JSON.parse(review.localRaw)},'alttl-before-import.json');review.downloaded=true;$('import-ack').disabled=false;$('import-status').textContent='備份已開始下載，請確認檔案保存後勾選。';}catch(e){review.downloaded=false;$('import-ack').checked=false;$('import-ack').disabled=true;$('import-status').textContent='備份失敗：'+e.message;}gate();};
 $('import-ack').onchange=gate;
 $('import-apply').onclick=async()=>{if(!review||$('import-apply').disabled)return;const selected=new Set([...document.querySelectorAll('[data-diff]:checked')].map(el=>{const r=review.rows[Number(el.dataset.diff)];return r.group+'/'+r.id;}));busy=true;try{await store.checkpoint('匯入前');progress=await store.update(p=>applyDifferences(p,review.rows,selected,$('older-ack').checked),review.stamp);lastUndo=null;$('undo').hidden=true;review=null;$('import-dialog').close();message('已套用選定差異，原文與快照均保留。');render(true);}catch(e){$('import-status').textContent=e.message;if(e.message.includes('過期'))review.expired=true;gate();}finally{busy=false;drainUpdates();}};
 $('import-close').onclick=()=>{$('import-dialog').close();review=null;};
 $('import-dialog').addEventListener('close',()=>{review=null;$('open-backup').focus();});
 $('backup-dialog').addEventListener('close',()=>$('open-backup').focus());
$('layout-dialog').addEventListener('close',()=>figureTrigger?.isConnected&&figureTrigger.focus({preventScroll:true}));
document.addEventListener('error',event=>{const img=event.target;if(img?.tagName!=='IMG'||!img.closest('.layout-image'))return;img.closest('.layout-image').querySelector('.image-error').hidden=false;},true);
try{const response=await fetch('./data.json');if(!response.ok)throw Error('攻略資料讀取失敗：'+response.status);data=await response.json();if(data.gameId!==gameId||data.puzzles?.length!==79||data.trophies?.length!==48)throw Error('攻略資料不完整');progress=await store.open();ready=true;reset();target=params().get('target')||'';if(target)status='all';$('menu').open=matchMedia('(min-width:721px)').matches;render();message('進度已載入，操作會保存於此瀏覽器。');if(target)requestAnimationFrame(()=>$('entry-'+target)?.scrollIntoView());}
catch(e){$('main').innerHTML='<h1>無法載入</h1><p>'+esc(e.message)+'</p><p>已停止寫入，原有資料不歸零。</p><button id="reload">重新載入</button><button id="raw-export">下載原始封存</button>';$('reload').onclick=()=>location.reload();$('raw-export').onclick=safely(async()=>download(await store.exportAll(),'alttl-unreadable-original.json'));message('載入失敗，已停止進度寫入。');}
